set -e
cd "$(dirname "$0")"
dd if=/dev/zero of=site/big.bin bs=1000 count=100
surl --directory site http://127.0.0.1:8080/ &
sleep 1
curl -s -o big.bin --limit-rate 25k -w "%{size_download} bytes at %{speed_download} bytes/s in %{time_total} s\n" http://127.0.0.1:8080/big.bin
kill $(jobs -p)
